const state=JSON.parse(localStorage.getItem('raidru-standalone')||'{}');
const RAIDRU_SCHEMA='0.7.4-map-calibration';
const VASHNIK_PLAN_VERSION='0.8.2-vashnik-russian-ui-v2';
const NEKZALI_PLAN_VERSION='0.8.4-nekzali-wcl-heroic-v1';
const SENTINELS_PLAN_VERSION='0.8.5-sentinels-wcl-heroic-v1';
// Важно: миграции вызываются только после инициализации encounterLibrary и остальных const.
// Иначе normalizeScene() попадает в temporal dead zone encounterLibrary на первом запуске/старом localStorage.
function runStartupMigrations(){
  let changed=false;
  const needsVashnikMigration=state._vashnikPlanVersion!==VASHNIK_PLAN_VERSION;
  const needsNekzaliMigration=state._nekzaliPlanVersion!==NEKZALI_PLAN_VERSION;
  const needsSentinelsMigration=state._sentinelsPlanVersion!==SENTINELS_PLAN_VERSION;
  // 0.7.4 геометрически калибрует все встроенные сцены под реальные изображения арен.
  // Сцены и таймлайн пересобираются один раз; прогресс, заметки, избранное и состав сохраняются.
  if(state._schema!==RAIDRU_SCHEMA){
    for(const b of raid){
      // Vashnik имеет отдельную 0.8.x-миграцию, которая сохраняет пользовательские сцены/ростер.
      // Не сбрасываем его здесь, иначе свежий preset ошибочно станет 'custom' и продублируется.
      if((b.id==='vashnik'&&needsVashnikMigration)||(b.id==='nekzali'&&needsNekzaliMigration)||(b.id==='sentinels'&&needsSentinelsMigration))continue;
      if(state[b.id]){
        state[b.id].scenes=bossPresetScenes(b.id);
        // defaultTimeline() безопасно вызывать здесь: encounterLibrary уже инициализирован.
        state[b.id].timelineV3=defaultTimeline(b.id);
      }
    }
    state._schema=RAIDRU_SCHEMA;
    changed=true;
  }

  if(needsNekzaliMigration){
    const saved=state.nekzali;
    if(saved?.scenes?.length){
      const oldNames=new Set([
        'Пулл — контроль Колодца','1-я волна аддов','Разрыв сущности — вынос',
        'Обстрел одержимости','Переход — Голодный костёр','Финал — героизм',
        'Пулл — Колодец всегда свободен','0:18 Разрыв сущности — культистов на край',
        '0:29 Обстрел одержимости — длинная линия','0:56 Амани — босса к активным гробницам',
        '1:22 Воспламенение + следующая волна','4:06 Переход — Ритуал пробуждения',
        '4:59 Голодный костёр — soak и Кремация','6:33 Раскручивание — героизм',
        '6:50+ Призыв — Амани и Обстрел до убийства'
      ]);
      const oldScenes=saved.scenes||[];
      const custom=oldScenes.filter(sc=>!oldNames.has(sc?.name));
      const fresh=bossPresetScenes('nekzali');
      for(let i=0;i<fresh.length;i++){
        const keep=(oldScenes[i]?.tokens||[]).filter(t=>{
          const m=t?.[5]||{};
          return ['roster','class'].includes(m.kind)||(m.kind==='encounter'&&!m.autoScenario)||(t?.[2]==='marker'&&raidMarkerKey(t?.[1]));
        });
        if(keep.length){
          const ids=new Set((fresh[i].tokens||[]).map(t=>t[0]));
          const hasRoster=keep.some(t=>['roster','class'].includes(t?.[5]?.kind));
          if(hasRoster)fresh[i].tokens=(fresh[i].tokens||[]).filter(t=>!['tank','healer','melee','ranged'].includes(t?.[2]));
          for(const t of keep)if(!ids.has(t[0]))fresh[i].tokens.push(t);
        }
      }
      saved.scenes=[...fresh,...custom];
      saved.timelineV3=defaultTimeline('nekzali');
    }
    state._nekzaliPlanVersion=NEKZALI_PLAN_VERSION;
    state._arenaMaskVersion='';
    changed=true;
  }

  if(needsSentinelsMigration){
    const saved=state.sentinels;
    if(saved?.scenes?.length){
      const oldNames=new Set([
        'Старт — две стабильные группы','Сгущение яда — слизень','Спиральные токсины — мини-группы',
        'Интермиссия — стазис','Повтор цикла — слизень + токсины','Поздний цикл — аккуратный дожим',
        'Пулл — две стороны и 40+ ярдов','0:10 Сгущение яда — быстрый свитч','0:15 Токсичные капли + Осквернение',
        '0:18 Инъекции и Нестабильная миазма','0:46 Ядовитый стазис — общий сбор','1:13 Повтор цикла — слизень после стазиса',
        '2:34–6:04 Средние стазисы — ровный темп','7:45 Последний стазис и дожим'
      ]);
      const oldScenes=saved.scenes||[];
      const custom=oldScenes.filter(sc=>!oldNames.has(sc?.name));
      const fresh=bossPresetScenes('sentinels');
      for(let i=0;i<fresh.length;i++){
        const keep=(oldScenes[i]?.tokens||[]).filter(t=>{
          const m=t?.[5]||{};
          return ['roster','class'].includes(m.kind)||(m.kind==='encounter'&&!m.autoScenario)||(t?.[2]==='marker'&&raidMarkerKey(t?.[1]));
        });
        if(keep.length){
          const ids=new Set((fresh[i].tokens||[]).map(t=>t[0]));
          const hasRoster=keep.some(t=>['roster','class'].includes(t?.[5]?.kind));
          if(hasRoster)fresh[i].tokens=(fresh[i].tokens||[]).filter(t=>!['tank','healer','melee','ranged'].includes(t?.[2]));
          for(const t of keep)if(!ids.has(t[0]))fresh[i].tokens.push(t);
        }
      }
      saved.scenes=[...fresh,...custom];
      saved.timelineV3=defaultTimeline('sentinels');
    }
    state._sentinelsPlanVersion=SENTINELS_PLAN_VERSION;
    state._arenaMaskVersion='';
    changed=true;
  }

  if(needsVashnikMigration){
    const saved=state.vashnik;
    if(saved?.scenes?.length){
      const oldNames=new Set(['Старт — южный источник','Поглощение 1 — источник А + Б','Живые яды — перехват аддов','Поглощение 2 — источник А + В','Сифонная инфекция — хил-КД','Поздний цикл — дожим','Пулл — готовим Тень + Пламя','0:10 Plague Froth — вынос','0:20 Imbibe #1 — Тень + Пламя','0:30 Malignant Catalyst — закрыть Bile','Adaptive Infection — развод по типу','1:44 Imbibe #2 — Кровь + Пламя','3:08 Imbibe #3 — Кровь + Тень','Поздние циклы — повтор треугольника']);
      const oldScenes=saved.scenes||[];
      const custom=oldScenes.filter(sc=>!oldNames.has(sc?.name));
      const fresh=bossPresetScenes('vashnik');
      for(let i=0;i<fresh.length;i++){
        const keep=(oldScenes[i]?.tokens||[]).filter(t=>{
          const m=t?.[5]||{};
          return ['roster','class'].includes(m.kind)||(m.kind==='encounter'&&!m.autoScenario)||(t?.[2]==='marker'&&raidMarkerKey(t?.[1]));
        });
        if(keep.length){
          const ids=new Set((fresh[i].tokens||[]).map(t=>t[0]));
          const hasRoster=keep.some(t=>['roster','class'].includes(t?.[5]?.kind));
          if(hasRoster)fresh[i].tokens=(fresh[i].tokens||[]).filter(t=>!['tank','healer','melee','ranged'].includes(t?.[2]));
          for(const t of keep)if(!ids.has(t[0]))fresh[i].tokens.push(t);
        }
      }
      saved.scenes=[...fresh,...custom];
      saved.timelineV3=defaultTimeline('vashnik');
    }
    state._vashnikPlanVersion=VASHNIK_PLAN_VERSION;
    state._arenaMaskVersion='';
    changed=true;
  }
  if(changed)localStorage.setItem('raidru-standalone',JSON.stringify(state));
}
