function pointInsideArenaPoly(x,y,poly){let yes=false,j=poly.length-1;for(let i=0;i<poly.length;i++){const [xi,yi]=poly[i],[xj,yj]=poly[j];if(((yi>y)!=(yj>y))&&(x<(xj-xi)*(y-yi)/((yj-yi)||1e-9)+xi))yes=!yes;j=i}return yes}
function arenaZonesFor(id,sceneName='',allFragments=false){const g=arenaCalibration[id];if(!g)return null;if(id==='ulatek'&&/Фаза\s*3|P3|дожим|сужение/i.test(String(sceneName||'')))return allFragments?(g.p3All||g.p3Safe||g.zones):(g.p3Safe||g.p3All||g.zones);return g.zones}
function arenaPointValid(id,x,y,sceneName='',margin=0,allFragments=false){const zones=arenaZonesFor(id,sceneName,allFragments);if(!zones?.length)return true;const pts=[[0,0]];if(margin>0)for(let a=0;a<360;a+=30){const r=a*Math.PI/180;pts.push([Math.cos(r)*margin,Math.sin(r)*margin])}return pts.every(([dx,dy])=>zones.some(poly=>pointInsideArenaPoly(x+dx,y+dy,poly)))}
function tokenArenaMargin(t){const meta=t?.[5]||{},type=t?.[2]||'';if(type==='boss'||meta.category==='boss')return 3.3;if(['roster','class'].includes(meta.kind))return 2.45;if(['tank','healer','melee','ranged'].includes(type))return 2.35;if(type==='marker')return 1.8;if(meta.kind==='encounter')return 2.15;return 2}
function hardArenaPoint(id,x,y,sceneName='',margin=0,allFragments=false){
  x=Math.max(2,Math.min(98,Number(x)||50));y=Math.max(2,Math.min(98,Number(y)||50));
  if(arenaPointValid(id,x,y,sceneName,margin,allFragments))return{x,y};
  for(let n=1;n<=120;n++){const d=n*.35,steps=Math.max(24,Math.ceil(Math.PI*2*d/.65));for(let i=0;i<steps;i++){const a=Math.PI*2*i/steps,qx=x+Math.cos(a)*d,qy=y+Math.sin(a)*d;if(qx>=2&&qx<=98&&qy>=2&&qy<=98&&arenaPointValid(id,qx,qy,sceneName,margin,allFragments))return{x:qx,y:qy}}}
  const zones=arenaZonesFor(id,sceneName,allFragments)||[];let best=null;for(const poly of zones){const cx=poly.reduce((s,p)=>s+p[0],0)/poly.length,cy=poly.reduce((s,p)=>s+p[1],0)/poly.length,d=(cx-x)**2+(cy-y)**2;if(!best||d<best.d)best={d,x:cx,y:cy}}return best?{x:best.x,y:best.y}:{x,y};
}
function snapArenaPoint(id,x,y,sceneName='',margin=0){x=Math.max(2,Math.min(98,Number(x)||50));y=Math.max(2,Math.min(98,Number(y)||50));if(!plannerArenaSnap)return{x,y};return hardArenaPoint(id,x,y,sceneName,margin,false)}
function correctStoredSceneGeometry(sc,id){if(!sc)return 0;let changed=0;for(const t of (sc.tokens||[])){const q=hardArenaPoint(id,t[3],t[4],sc.name,tokenArenaMargin(t),false);if(Math.hypot(q.x-t[3],q.y-t[4])>.05){t[3]=+q.x.toFixed(2);t[4]=+q.y.toFixed(2);changed++}}for(const pts of Object.values(sc.routes||{}))for(const p of pts){const q=hardArenaPoint(id,p.x,p.y,sc.name,.8,false);if(Math.hypot(q.x-p.x,q.y-p.y)>.05){p.x=+q.x.toFixed(2);p.y=+q.y.toFixed(2);changed++}}return changed}
