const BUILTIN_SCENE_VERSION='0.8.8-explorers-heroic-v1';
function isPreservedUserToken(t){
  const meta=t?.[5]||{};
  if(meta.kind==='roster'||meta.kind==='class')return true;
  if(meta.kind==='encounter'&&!meta.autoScenario)return true;
  if(t?.[2]==='marker'&&raidMarkerKey(t[1]))return true;
  return false;
}
function migrateBuiltInScenes(){
  if(state._builtinSceneVersion===BUILTIN_SCENE_VERSION)return 0;
  let changed=0;
  for(const b of raid){
    const saved=state[b.id];
    if(!saved?.scenes)continue;
    const latest=presetScenes[b.id]||[];
    const byName=new Map(latest.map(x=>[x.name,x]));
    saved.scenes=saved.scenes.map(old=>{
      const fresh=byName.get(old.name);
      if(!fresh)return old; // пользовательская отдельная сцена
      const keep=(old.tokens||[]).filter(isPreservedUserToken);
      const next=JSON.parse(JSON.stringify(fresh));
      // Если пользователь уже разложил реальный состав, не возвращаем T/H/M/R placeholders.
      const hasRoster=keep.some(t=>['roster','class'].includes(t?.[5]?.kind));
      if(hasRoster)next.tokens=(next.tokens||[]).filter(t=>!['tank','healer','melee','ranged'].includes(t?.[2]));
      const ids=new Set((next.tokens||[]).map(t=>t[0]));
      for(const t of keep)if(!ids.has(t[0]))next.tokens.push(t);
      // Пользовательское затемнение/zoom карты не сбрасываем.
      if(old.map)next.map=old.map;
      changed++;
      return next;
    });
  }
  state._builtinSceneVersion=BUILTIN_SCENE_VERSION;
  // Force the hard-mask pass once more after replacing authored geometry.
  state._arenaMaskVersion='';
  localStorage.setItem('raidru-standalone',JSON.stringify(state));
  return changed;
}
const BUILTIN_SCENES_MIGRATED=migrateBuiltInScenes();
const ARENA_MASK_VERSION='0.8.8-shared-2608-viewports-v2';
if(state._arenaMaskVersion!==ARENA_MASK_VERSION){
  let adjusted=0;
  for(const b of raid){const saved=state[b.id];if(!saved?.scenes)continue;for(const sc of saved.scenes)adjusted+=correctStoredSceneGeometry(sc,b.id)}
  state._arenaMaskVersion=ARENA_MASK_VERSION;state._arenaMaskAdjusted=adjusted;
  localStorage.setItem('raidru-standalone',JSON.stringify(state));
}

