function parseTime(v){
  if(typeof v==='number')return v;
  const s=String(v||'').trim();
  if(/^\d+:\d+$/.test(s)){const [m,sec]=s.split(':').map(Number);return m*60+sec}
  if(/^\d+(?:\.\d+)?$/.test(s))return Number(s);
  return NaN;
}
