function exportReplayJson(){const d=replayState().data;if(!d)return toast('Replay ещё не загружен');const blob=new Blob([JSON.stringify(d,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`raidru-replay-${current}.json`;a.click();URL.revokeObjectURL(a.href)}
function autoCalibrateReplay(){const r=replayState();r.cal={rot:0,flipX:false,flipY:false,scale:92,offX:0,offY:0}}
function setReplayCal(k,v){const r=replayState();if(k==='flipX'||k==='flipY')r.cal[k]=!!v;else r.cal[k]=+v;save();updateReplayDom(true)}
function resetReplayCal(){replayState().cal={rot:0,flipX:false,flipY:false,scale:92,offX:0,offY:0};save();render()}
function setReplayTime(v){stopReplay();replayClock=Math.max(0,Math.min(replayDuration(replayState().data),+v||0));updateReplayDom(true)}
function setReplaySpeed(v){replaySpeed=+v||1}
function replayStep(ms){setReplayTime(replayClock+ms)}
function stopReplay(){replayPlaying=false;if(replayRAF)cancelAnimationFrame(replayRAF);replayRAF=null;replayLastTs=0}
function toggleReplay(){if(replayPlaying){stopReplay();updateReplayDom(true);return}const d=replayState().data;if(!d)return toast('Сначала загрузи replay');if(replayClock>=replayDuration(d)-50)replayClock=0;replayPlaying=true;replayLastTs=performance.now();replayRAF=requestAnimationFrame(replayTick);updateReplayPlayButton()}
function replayTick(now){if(!replayPlaying)return;const dt=(now-replayLastTs)*replaySpeed;replayLastTs=now;replayClock+=dt;const dur=replayDuration(replayState().data);if(replayClock>=dur){replayClock=dur;stopReplay()}updateReplayDom(false);if(replayPlaying)replayRAF=requestAnimationFrame(replayTick)}
function updateReplayPlayButton(){const b=el('#replayPlay');if(b)b.textContent=replayPlaying?'■ Пауза':'▶ Играть'}
function replayActorHtml(a,data,t){const p=positionAt(data,a.id,t);if(!p)return '';const q=data.normalizedPercent?{x:p.x,y:p.y}:replayPoint(data,p.x,p.y);const role=replayRole(a),ck=detectClassKey(a.subType||a.class||''),c=wowClass(ck);return `<div class="replayActor ${role}${c?' hasClassIcon':''}" data-actor="${a.id}" style="left:${q.x}%;top:${q.y}%" title="${esc(a.name)}${c?' · '+esc(c.name):''}">${c?`<img src="${c.icon}" alt="">`:''}<b>${esc(shortActorName(a.name))}</b></div>`}
function replayMapSource(){const d=replayState().data;if(current==='ulatek'&&d){const p3=(bossState(current).timelineV3.find(e=>/фаза 3|героизм на p3/i.test(e.label))?.time||145)*1000;if(replayClock>=p3)return arenaMaps.ulatek_p3}return arenaMaps[current]||arenaMaps.nekzali}
function updateReplayDom(force=false){
 const d=replayState().data;if(!d)return;const dur=replayDuration(d);const slider=el('#replaySlider');if(slider){slider.max=dur;slider.value=replayClock}const tm=el('#replayTime');if(tm)tm.textContent=`${fmtTime(replayClock/1000)} / ${fmtTime(dur/1000)}`;const ev=replayEventNear(d,replayClock),evn=el('#replayNow');if(evn)evn.innerHTML=ev?`<b>${esc(ev.label)}</b><small>${esc(ev.type)}</small>`:'<b>Движение рейда</b><small>между событиями</small>';
 const layer=el('#replayActors');if(layer){const actors=replayActors(d).filter(a=>replaySelectedActor==='all'||String(a.id)===String(replaySelectedActor));layer.innerHTML=actors.map(a=>replayActorHtml(a,d,replayClock)).join('')}
 const im=el('#replayMapImage');if(im&&im.getAttribute('src')!==replayMapSource())im.setAttribute('src',replayMapSource());updateReplayPlayButton();
}
function selectReplayActor(v){replaySelectedActor=v;updateReplayDom(true)}
function createPlanFromReplay(){
 const r=replayState(),d=r.data;if(!d?.positions?.length)return toast('Сначала загрузи replay');const bs=bossState(current),base=bossPresetScenes(current),events=[...bs.timelineV3].sort((a,b)=>a.time-b.time),actors=replayActors(d);if(!actors.length)return toast('В replay нет игроков');
 const newScenes=events.map((e,i)=>{const template=deep(base[Math.min(e.scene,base.length-1)]||base[0]||defaultScene()),t=e.time*1000;const staticTokens=(template.tokens||[]).filter(x=>['marker','boss'].includes(x[2]));const playerTokens=actors.map(a=>{const p=positionAt(d,a.id,t);if(!p)return null;const q=d.normalizedPercent?{x:p.x,y:p.y}:replayPoint(d,p.x,p.y);const rt=replayRole(a),ck=detectClassKey(a.subType||a.class||'');return [`wcl-${a.id}`,shortActorName(a.name),rt,q.x,q.y,{kind:'roster',rosterId:`wcl-${a.id}`,classKey:ck,role:rt==='tank'?'tank':rt==='healer'?'healer':'dps',range:rt==='melee'?'melee':'ranged'}]}).filter(Boolean);template.name=`${fmtTime(e.time)} · ${e.label}`;template.note=`Автоматически создано из replay: ${e.label}. Можно свободно редактировать как обычный план RaidRU.`;template.tokens=[...staticTokens,...playerTokens];template.routes={};return normalizeScene(template,current,i)});
 bs.scenes=newScenes;bs.timelineV3=events.map((e,i)=>({...e,id:uid(),scene:i}));sceneIndex=0;save();toast(`Создано ${newScenes.length} редактируемых сцен из replay`);view='planner';render();
}

function buildShareUrl(){const payload={v:5,boss:current,diff,role,data:bossState(current)};return location.origin+location.pathname+'#share='+safeB64Encode(payload)}
function restoreFromHash(){try{if(!location.hash.startsWith('#share='))return;const p=safeB64Decode(location.hash.slice(7));if(p?.boss&&p?.data){state[p.boss]=p.data;current=p.boss;diff=p.diff||diff;role=p.role||role;toast('Стратегия загружена из ссылки')}}catch(e){console.warn(e)}}
function save(){state.current=current;state.role=role;state.diff=diff;state.view=view;state.priestMode=priestMode;state.showPaths=showPaths;state.plannerPaletteTab=plannerPaletteTab;state.plannerSpawnMode=plannerSpawnMode;state.plannerArenaSnap=plannerArenaSnap;state.plannerIconTab=plannerIconTab;localStorage.setItem('raidru-standalone',JSON.stringify(state))}
function render(){
  save();const b=raid.find(x=>x.id===current),bs=bossState(current);
  el('#app').innerHTML=`<div class="shell"><aside><div class="brand"><div class="mark">R</div><div><b>RaidRU</b><small>рейдовые тактики по-русски</small></div></div><div class="season"><small>Midnight · Сезон 2</small><b>Ядовитая бездна</b></div><input class="search" placeholder="Найти босса…" oninput="filterBoss(this.value)"><div class="bosses">${orderedRaid().map(x=>`<button data-name="${esc((x.name+' '+x.en).toLowerCase())}" class="${x.id===current?'on':''}" onclick="chooseBoss('${x.id}')"><i>${x.order}</i><span><b>${x.name}</b><small>Босс ${x.order}</small></span><em>${bossState(x.id).favorite?'★':''}</em></button>`).join('')}</div><div class="version">RaidRU 0.8.8 · единая карта рейда</div></aside><main><header>${[['dashboard','Рейд'],['guide','Тактика'],['player','План: просмотр'],['planner','Планировщик'],['timeline','Таймлайн'],['roster','Состав'],['notes','Заметки'],['glossary','Словарь']].map(x=>`<button class="${view===x[0]?'on':''}" onclick="setView('${x[0]}')">${x[1]}</button>`).join('')}<span></span><button class="priest ${priestMode?'on':''}" onclick="togglePriest()">♥ Холи-прист</button><button onclick="sharePlan()">↗ Поделиться</button><button onclick="exportPlan()">⇩ Экспорт</button><label class="importBtn">⇧ Импорт<input type="file" accept="application/json,.json" onchange="importPlanFile(this.files[0])"></label></header>${view==='dashboard'?dashboardHero():`<section class="hero"><div><small>MIDNIGHT / ЯДОВИТАЯ БЕЗДНА / БОСС ${b.order}</small><div class="title"><h1>${b.name}</h1><button onclick="fav()">${bs.favorite?'★':'☆'}</button></div><p>${b.summary}</p></div><div class="heroRight"><div class="diff">${[['normal','Обычный'],['heroic','Героический'],['mythic','Эпохальный']].map(x=>`<button class="${diff===x[0]?'on':''}" onclick="setDiff('${x[0]}')">${x[1]}</button>`).join('')}</div><label>Освоение <b>${bs.progress}%</b><input type="range" min="0" max="100" step="10" value="${bs.progress}" oninput="setProgress(this.value)"></label></div></section>`}${content(b,bs)}<footer class="siteCredit">Карты и ресурсы для планирования: <a href="https://raidplan.io/" target="_blank" rel="noopener noreferrer">RaidPlan.io</a> · Единая карта рейда mapID 2608 и Heroic-тайминги: Warcraft Logs/RPGLogs · Иконки планировщика: локальные ассеты RaidRU · Рейдовые значки: игровые ресурсы сообщества</footer></main></div>`;
  if(view==='planner') setupPlanner();
  if(view==='player') setupPlayer();
}
function content(b,bs){if(view==='dashboard')return dashboard();if(view==='guide')return guide(b);if(view==='replay')return replayView(b,bs);if(view==='player')return player(b,bs);if(view==='planner')return planner(b,bs);if(view==='timeline')return timeline(b,bs);if(view==='roster')return rosterView();if(view==='notes')return notes(b,bs);return glossary(b)}
function dashboardHero(){const avg=Math.round(raid.reduce((a,x)=>a+bossState(x.id).progress,0)/raid.length);return `<section class="hero dashboardHero"><div><small>MIDNIGHT / СЕЗОН 2</small><div class="title"><h1>Ядовитая бездна</h1></div><div class="en">8 боссов · тактики и планировщик</div><p>Русские тактики, подробный таймлайн каждого босса, точные шаблоны сцен на арене, маршруты игроков и заметки РЛ.</p></div><div class="heroRight"><div class="raidProgress"><b>${avg}%</b><span>средний прогресс рейда</span></div><button class="primary" onclick="continueRaid()">Продолжить освоение →</button></div></section>`}
function dashboard(){return `<section class="page"><div class="stats"><div><b>${raid.filter(x=>bossState(x.id).progress>=100).length}/8</b><span>убито</span></div><div><b>${raid.filter(x=>bossState(x.id).favorite).length}</b><span>в избранном</span></div><div><b>${rosterState().length}</b><span>в составе</span></div><div><b>${raid.reduce((a,x)=>a+bossState(x.id).scenes.length,0)}</b><span>сцен</span></div></div><div class="bossCards">${orderedRaid().map(x=>{const st=bossState(x.id);return `<article onclick="openBoss('${x.id}')"><div class="bossThumb">${bossThumbMapHtml(x.id)}<span>${x.order}</span></div><div><small>Босс ${x.order}</small><h3>${x.name}</h3><p>${x.summary}</p><div class="progressLine"><i style="width:${st.progress}%"></i></div><footer><span>${st.progress}% освоено</span><b>${st.scenes.length} сцен · ${st.timelineV3.length} событий</b></footer></div></article>`}).join('')}</div><div class="dashboardActions"><button onclick="backupAll()">Скачать резервную копию RaidRU</button><button onclick="resetAllConfirm()">Сбросить локальные данные</button><span>Карта рейда: один исходник mapID 2608. Нек’зали, Погребённые часовые, Вашник и Потерянные исследователи уже показывают разные участки одной большой карты; Heroic-сцены и таймлайны остаются локальными для каждого босса.</span></div></section>`}
function continueRaid(){const r=orderedRaid();const x=r.find(x=>bossState(x.id).progress<100)||r[0];openBoss(x.id)}
function openBoss(id){current=id;view='guide';sceneIndex=0;playerSceneIndex=0;render()}
function rolebar(){return `<div class="rolebar">${Object.entries(roles).map(([k,v])=>`<button class="${role===k?'on':''}" onclick="setRole('${k}')">${v}</button>`).join('')}</div>`}
function guide(b){return `<section class="page">${rolebar()}<div class="grid"><div class="guide">${b.phases.map((p,i)=>`<article class="phase"><div class="phaseHead"><i>0${i+1}</i><div><h2>${p[0]}</h2><small>${p[1]||''}</small></div></div>${p[2].filter(m=>role==='all'||m[3].split(',').includes(role)||m[3].includes('all')).map(m=>`<div class="mech ${m[4]}"><strong>!</strong><div><h3>${m[0]}</h3><p>${m[2]}</p>${diff==='heroic'&&m[5]?`<em><b>Героический:</b> ${m[5]}</em>`:''}</div></div>`).join('')}</article>`).join('')}</div><div class="right"><div class="card"><h3>🎯 Главное на боссе</h3><p>${b.rl}</p><button onclick="copyText(${JSON.stringify(b.rl)})">Копировать</button></div>${priestMode?`<div class="card priestCard"><h3>♥ Холи-прист</h3><p>${b.heal}</p><div class="chips">${priest.slice(0,4).map(x=>`<span>${x[0]}</span>`).join('')}</div></div>`:''}<div class="card"><h3>🔥 Героизм</h3><b>${b.bl}</b></div><div class="card"><h3>🎬 Планировщик тактики</h3><p>Главный режим RaidRU: ключевые кадры, реальные точки арены, маршруты босса, зоны, назначения и привязанный таймлайн.</p><button onclick="setView('planner')">Открыть планировщик</button><button onclick="setView('player')">Проиграть план</button></div></div></div></section>`}
function raidMapViewportStyle(id){
  const v=raidMapViewports[id];if(!v)return null;
  const left=-(v.x/v.w)*100,top=-(v.y/v.h)*100;
  const width=(RAID_MAP_SIZE.w/v.w)*100,height=(RAID_MAP_SIZE.h/v.h)*100;
  return `--rm-left:${left}%;--rm-top:${top}%;--rm-width:${width}%;--rm-height:${height}%`;
}
function bossThumbMapHtml(id){
  const s=raidMapViewportStyle(id);
  if(!s)return `<img src="${arenaMaps[id]}" alt="" loading="lazy">`;
  return `<div class="bossThumbViewport"><img class="raidMapFull" src="${RAID_MAP_SOURCE}" alt="" loading="lazy" style="${s}"></div>`;
}
function arenaMapHtml(id,sc){
  const useUlatekP3 = id==='ulatek' && /фаза\s*3|дожим|разруш/i.test(String(sc?.name||''));
  const m=sc?.map||{zoom:100,x:0,y:0,dark:8};
  const scale=(Number(m.zoom)||100)/100;
  const viewportStyle=raidMapViewportStyle(id);
  if(viewportStyle){
    return `<div class="arenaMap arenaMap-${id} arenaMap-raid2608">
      <div class="raidMapViewportAdjust" style="transform:translate(${Number(m.x)||0}%,${Number(m.y)||0}%) scale(${scale})">
        <img class="arenaMapImage raidMapFull" src="${RAID_MAP_SOURCE}" alt="Карта рейда — ${esc(raid.find(x=>x.id===id)?.name||id)}"
          draggable="false" style="${viewportStyle}">
      </div>
    </div>`;
  }
  const src=(useUlatekP3?arenaMaps.ulatek_p3:arenaMaps[id])||arenaMaps.nekzali;
  return `<div class="arenaMap arenaMap-${id}${useUlatekP3? ' arenaMap-ulatek-p3':''}">
    <img class="arenaMapImage" src="${src}" alt="Карта арены ${esc(raid.find(x=>x.id===id)?.name||id)}"
      draggable="false"
      style="transform:translate(${Number(m.x)||0}%,${Number(m.y)||0}%) scale(${scale})">
  </div>`;
}
function sceneAttachedTime(bs,idx){const x=bs.timelineV3?.find(e=>+e.scene===+idx);return x?fmtTime(x.time):'—'}
function pathPreviewHtml(sc,next){
  if(!showPaths)return '';
  const m=next?new Map(next.tokens.map(t=>[t[0],t])):new Map();
  const shapes=sc.tokens.map(t=>{
    if(t[2]==='marker'||t[2]==='boss')return '';
    const pts=[{x:t[3],y:t[4]},...((sc.routes&&sc.routes[t[0]])||[])];
    const n=m.get(t[0]); if(n)pts.push({x:n[3],y:n[4]});
    if(pts.length<2)return '';
    const points=pts.map(p=>`${p.x},${p.y}`).join(' ');
    return `<polyline points="${points}" marker-end="url(#arr)" />`;
  }).join('');
  return `<svg class="pathPreview" viewBox="0 0 100 100" preserveAspectRatio="none"><defs><marker id="arr" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" /></marker></defs>${shapes}</svg>`;
}
function routeWaypointsHtml(sc,editable){
  if(!editable)return '';
  const out=[];
  Object.entries(sc.routes||{}).forEach(([tid,pts])=>pts.forEach((p,i)=>out.push(`<button class="waypoint ${routeTokenId===tid?'active':''}" data-route-token="${tid}" data-route-index="${i}" style="left:${p.x}%;top:${p.y}%" title="Точка маршрута ${i+1}. Перетащить; ПКМ — удалить">${i+1}</button>`)));
  return `<div class="waypoints">${out.join('')}</div>`;
}
function togglePaths(){showPaths=!showPaths;save();render()}
function effectHtml(e,editable=false){const style=`left:${e.x}%;top:${e.y}%;width:${e.w}%;height:${e.h}%;--rot:${Number(e.rot)||0}deg`;return `<div class="effect ${e.type} ${editable?'editable':''}" data-effect="${e.id}" style="${style}" title="${esc(e.label||effectLabels[e.type])}"></div>`}

function boxOverlap(a,b,pad=0){
  return !(a.r+pad<b.l || a.l-pad>b.r || a.b+pad<b.t || a.t-pad>b.b);
}
function effectLabelLayout(sc,{ignoreManual=false}={}){
  const tokens=(sc.tokens||[]).map(t=>({
    l:+t[3]-3.1,r:+t[3]+3.1,t:+t[4]-4.2,b:+t[4]+4.2
  }));
  const placed=[];
  return (sc.effects||[]).map((e,i)=>{
    const label=String(e.label||effectLabels[e.type]||'').trim();
    if(!label)return null;

    const lw=Math.max(9,Math.min(30,label.length*.58+4.5));
    const lh=5.2;
    const ew=Math.max(4,+e.w||12),eh=Math.max(4,+e.h||12);
    const ex=Number.isFinite(+e.x)?+e.x:50,ey=Number.isFinite(+e.y)?+e.y:50;
    const manual=!ignoreManual&&Number.isFinite(+e.labelDx)&&Number.isFinite(+e.labelDy);

    // Ручная позиция хранится как смещение от эффекта: если сам эффект двигают,
    // подпись следует за ним и сохраняет выбранное пользователем расположение.
    if(manual){
      const x=Math.max(lw/2+1.2,Math.min(100-lw/2-1.2,ex+(+e.labelDx||0)));
      const y=Math.max(lh/2+1.2,Math.min(100-lh/2-1.2,ey+(+e.labelDy||0)));
      const box={l:x-lw/2,r:x+lw/2,t:y-lh/2,b:y+lh/2};
      placed.push(box);
      return {x,y,box,pos:'manual',score:0,label,type:e.type,id:e.id,manual:true,anchorX:ex,anchorY:ey};
    }

    const dx=ew/2+lw/2+2.7,dy=eh/2+lh/2+2.8;
    const candidates=[
      {x:ex,y:ey-eh/2-3.6,pos:'top',base:0},
      {x:ex,y:ey+eh/2+3.6,pos:'bottom',base:1.5},
      {x:ex-ew/2-lw/2-2.5,y:ey,pos:'left',base:4},
      {x:ex+ew/2+lw/2+2.5,y:ey,pos:'right',base:4},
      {x:ex-dx*.72,y:ey-dy*.72,pos:'top-left',base:2.7},
      {x:ex+dx*.72,y:ey-dy*.72,pos:'top-right',base:2.7},
      {x:ex-dx*.72,y:ey+dy*.72,pos:'bottom-left',base:3.2},
      {x:ex+dx*.72,y:ey+dy*.72,pos:'bottom-right',base:3.2},
      {x:ex,y:ey-3,pos:'inside',base:28}
    ];

    let best=null;
    for(const c of candidates){
      const rawX=c.x,rawY=c.y;
      const x=Math.max(lw/2+1.2,Math.min(100-lw/2-1.2,rawX));
      const y=Math.max(lh/2+1.2,Math.min(100-lh/2-1.2,rawY));
      const box={l:x-lw/2,r:x+lw/2,t:y-lh/2,b:y+lh/2};
      let score=c.base+Math.abs(x-rawX)*9+Math.abs(y-rawY)*9;

      for(const tb of tokens){
        if(boxOverlap(box,tb,1.35))score+=210;
      }
      for(const pb of placed){
        if(boxOverlap(box,pb,1.75))score+=290;
      }

      const effectBox={l:ex-ew/2,r:ex+ew/2,t:ey-eh/2,b:ey+eh/2};
      if(c.pos!=='inside' && boxOverlap(box,effectBox,.65))score+=90;

      if(!best||score<best.score)best={x,y,box,pos:c.pos,score,label,type:e.type,id:e.id,manual:false,anchorX:ex,anchorY:ey};
    }
    placed.push(best.box);
    return best;
  }).filter(Boolean);
}
function effectLabelsHtml(sc,{editable=false}={}){
  const layout=effectLabelLayout(sc);
  const leaders=layout.filter(x=>x.manual&&Math.hypot(x.x-x.anchorX,x.y-x.anchorY)>3.5).map(x=>`<line class="effectLabelLeader" data-effect-label-line="${x.id}" x1="${x.anchorX}" y1="${x.anchorY}" x2="${x.x}" y2="${x.y}" vector-effect="non-scaling-stroke"></line>`).join('');
  return `<div class="effectLabels ${editable?'editable':''}"><svg class="effectLabelLeaders" viewBox="0 0 100 100" preserveAspectRatio="none">${leaders}</svg>${layout.map(x=>`<div class="effectCallout ${x.type} ${editable?'editable':''} ${x.manual?'manual':''}" data-effect-label="${x.id}" style="left:${x.x}%;top:${x.y}%" title="${editable?'Перетащи подпись. Shift — только по одной оси. Двойной клик или ПКМ — вернуть авто-позицию.':''}"><span>${esc(x.label)}</span></div>`).join('')}</div>`;
}
function arenaHtml(sc,{editable=false,player=false,next=null}={}){const dark=Math.max(0,Math.min(65,Number(sc?.map?.dark)||0))/100;return `<div id="${player?'playerArena':'arena'}" class="arena ${player?'playArena':''} arena-${current} ${routeEdit&&editable?'routeMode':''}">${arenaMapHtml(current,sc)}<div class="mapShade" style="background:rgba(0,0,0,${dark})"></div>${pathPreviewHtml(sc,next)}${routeWaypointsHtml(sc,editable)}<div class="arenaLabel">${esc(sc.name)}</div><div class="effects">${(sc.effects||[]).map(e=>effectHtml(e,editable)).join('')}</div><div class="tokens">${sc.tokens.map(t=>`<div class="token ${t[2]}${tokenExtraClass(t)} ${routeTokenId===t[0]&&routeEdit?'routeSelected':''}" data-id="${t[0]}" title="${esc(tokenNativeTitle(t,editable))}" data-label="${esc(tokenHoverLabel(t,editable))}" style="left:${t[3]}%;top:${t[4]}%">${tokenInnerHtml(t)}</div>`).join('')}</div>${effectLabelsHtml(sc,{editable})}</div>`}
function replayView(b,bs){
 const r=replayState(),d=r.data,actors=d?replayActors(d):[],dur=d?replayDuration(d):1,cal=r.cal||{};const src=replayMapSource();
 return `<section class="page replayPage"><div class="replayImport card"><div><h3>Replay — экспериментальный локальный инструмент</h3><p>Replay оставлен только как внутренний локальный инструмент. Для проверки можно импортировать ранее сохранённый replay JSON; основной продукт — планировщик.</p></div><div class="replayButtons"><button onclick="loadDemoReplay()">Демо из плана</button><label class="importBtn">Импорт replay JSON<input type="file" accept="application/json,.json" onchange="importReplayJson(this.files[0])"></label>${d?'<button onclick="exportReplayJson()">Экспорт replay JSON</button><button class="rehearse" onclick="createPlanFromReplay()">✦ Создать план из replay</button>':''}</div><small>Сетевой импорт WCL в этой сборке отключён.</small></div>
 ${d?`<div class="replayGrid"><div><div id="replayArena" class="arena replayArena"><div class="arenaMap"><img id="replayMapImage" class="arenaMapImage" src="${src}" draggable="false"></div><div class="mapShade" style="background:rgba(0,0,0,.06)"></div><div id="replayActors" class="replayActors">${actors.map(a=>replayActorHtml(a,d,replayClock)).join('')}</div><div class="arenaLabel">WCL · ${esc(d.fight?.name||b.name)}</div></div><div class="replayTransport"><button onclick="replayStep(-1000)">−1с</button><button onclick="replayStep(-5000)">−5с</button><button id="replayPlay" class="primary" onclick="toggleReplay()">${replayPlaying?'■ Пауза':'▶ Играть'}</button><button onclick="replayStep(5000)">+5с</button><button onclick="replayStep(1000)">+1с</button><select onchange="setReplaySpeed(this.value)">${[.25,.5,1,1.5,2,4].map(x=>`<option value="${x}" ${replaySpeed===x?'selected':''}>${x}×</option>`).join('')}</select><b id="replayTime">${fmtTime(replayClock/1000)} / ${fmtTime(dur/1000)}</b></div><input id="replaySlider" class="replaySlider" type="range" min="0" max="${dur}" value="${replayClock}" step="100" oninput="setReplayTime(this.value)"><div id="replayNow" class="replayNow">${(()=>{const e=replayEventNear(d,replayClock);return e?`<b>${esc(e.label)}</b><small>${esc(e.type)}</small>`:'<b>Движение рейда</b><small>между событиями</small>'})()}</div></div>
 <aside class="replaySide"><div class="card"><h3>Игроки</h3><select onchange="selectReplayActor(this.value)"><option value="all">Весь рейд</option>${actors.map(a=>`<option value="${a.id}" ${String(replaySelectedActor)===String(a.id)?'selected':''}>${esc(a.name)}</option>`).join('')}</select><p>${actors.length} игроков · ${(d.positions||[]).length} координатных точек</p></div><div class="card"><h3>Калибровка карты</h3><label>Поворот<select onchange="setReplayCal('rot',this.value)">${[0,90,180,270].map(x=>`<option value="${x}" ${+cal.rot===x?'selected':''}>${x}°</option>`).join('')}</select></label><label><input type="checkbox" ${cal.flipX?'checked':''} onchange="setReplayCal('flipX',this.checked)"> Отразить X</label><label><input type="checkbox" ${cal.flipY?'checked':''} onchange="setReplayCal('flipY',this.checked)"> Отразить Y</label><label>Масштаб <b>${cal.scale||100}%</b><input type="range" min="60" max="160" value="${cal.scale||100}" oninput="setReplayCal('scale',this.value)"></label><label>Сдвиг X <b>${cal.offX||0}</b><input type="range" min="-30" max="30" value="${cal.offX||0}" oninput="setReplayCal('offX',this.value)"></label><label>Сдвиг Y <b>${cal.offY||0}</b><input type="range" min="-30" max="30" value="${cal.offY||0}" oninput="setReplayCal('offY',this.value)"></label><button onclick="resetReplayCal()">Сбросить калибровку</button></div><div class="card"><h3>События лога</h3><div class="replayEvents">${(d.events||[]).slice(0,80).map(e=>`<button onclick="setReplayTime(${+e.t||0})"><time>${fmtTime((+e.t||0)/1000)}</time><span>${esc(e.label)}</span></button>`).join('')||'<p>События не найдены, но координаты доступны.</p>'}</div></div></aside></div>`:`<div class="emptyReplay"><b>Пока replay не загружен</b><p>Можно проверить интерфейс кнопкой «Демо из плана» или импортировать локальный replay JSON.</p></div>`}</section>`;
}
function player(b,bs){const sc=bs.scenes[Math.min(playerSceneIndex,bs.scenes.length-1)],next=bs.scenes[playerSceneIndex+1]||null;const events=bs.timelineV3;return `<section class="page playerPage"><div class="playerTop"><div><button onclick="playerPrev()">‹</button><b>${esc(sc.name)}</b><span class="keyBadge">Кадр ${playerSceneIndex+1}/${bs.scenes.length} · ${sceneAttachedTime(bs,playerSceneIndex)}</span><button onclick="playerNext()">›</button></div><div><button class="${showPaths?'on':''}" onclick="togglePaths()">⇢ Траектории</button><select onchange="setPlayerSpeed(this.value)"><option value="0.5" ${playerSpeed===.5?'selected':''}>0.5×</option><option value="1" ${playerSpeed===1?'selected':''}>1×</option><option value="1.5" ${playerSpeed===1.5?'selected':''}>1.5×</option><option value="2" ${playerSpeed===2?'selected':''}>2×</option></select><button class="rehearse" onclick="togglePlayback()">${playerPlaying?'■ Стоп':'▶ Проиграть бой'}</button></div></div><div class="playerLayout"><div>${arenaHtml(sc,{player:true,next})}<div class="sceneCaption"><b>${esc(sc.name)}</b><p>${esc(sc.note)}</p><small>Следующий ключевой кадр: ${next?esc(next.name):'финал'}</small></div></div><aside class="eventRail"><h3>Таймлайн</h3>${events.map((e,i)=>`<button class="${e.scene===playerSceneIndex?'on':''}" onclick="jumpEvent(${i})"><time>${fmtTime(e.time)}</time><span><b>${esc(e.label)}</b><small>${eventTypes[e.type]||e.type} · кадр ${e.scene+1}</small></span></button>`).join('')}</aside></div><div class="playScrubber">${events.map((e,i)=>`<button class="${e.scene===playerSceneIndex?'on':''}" style="left:${timelinePct(e.time,events)}%" onclick="jumpEvent(${i})" title="${fmtTime(e.time)} · ${esc(e.label)}"></button>`).join('')}</div><div class="playerLegend"><span><i class="lg tank"></i>Танк</span><span><i class="lg healer"></i>Хил</span><span><i class="lg dps"></i>ДД</span><span><i class="lg danger"></i>Опасность</span><span><i class="lg path"></i>Траектория к следующему кадру</span></div></section>`}
function timelinePct(t,events){const max=Math.max(1,...events.map(e=>Number(e.time)||0));return Math.min(100,(Number(t)||0)/max*100)}
function planner(b,bs){const sc=bs.scenes[Math.min(sceneIndex,bs.scenes.length-1)];const movable=sc.tokens.filter(t=>!['marker','boss'].includes(t[2]));if(!routeTokenId||!movable.some(t=>t[0]===routeTokenId))routeTokenId=movable[0]?.[0]||null;return `<section class="page plannerPage"><div class="plannerTop"><div><button onclick="prevScene()">‹</button><input id="sceneName" value="${esc(sc.name)}"><small>${sceneIndex+1}/${bs.scenes.length}</small><button onclick="nextScene()">›</button></div><div><button onclick="setView('player')">▶ Просмотр</button><button onclick="loadBossPreset()">Шаблон босса</button><button onclick="addScene()">＋ Сцена</button><button onclick="resetScene()">↻ Сброс</button><button class="red" onclick="delScene()">Удалить</button></div></div><div class="sceneStrip">${bs.scenes.map((x,i)=>`<button class="${i===sceneIndex?'on':''}" onclick="goScene(${i})"><b>${i+1}</b><span>${esc(x.name)}</span></button>`).join('')}</div><div class="planGrid"><div class="plannerCanvas">${arenaHtml(sc,{editable:true,next:bs.scenes[sceneIndex+1]||null})}<div class="sceneMeta"><button class="${showPaths?'on':''}" onclick="togglePaths()">⇢ Траектории</button><span class="keyBadge">Кадр · ${sceneAttachedTime(bs,sceneIndex)}</span><label>Длительность <input id="sceneDuration" type="number" min="1" max="120" value="${sc.duration||8}"> сек.</label></div><textarea id="sceneNote" placeholder="Описание сцены…">${esc(sc.note)}</textarea></div><div class="toolbox paletteToolbox">${plannerPaletteHtml()}<details class="advancedTools"><summary>Дополнительные инструменты</summary><div class="advancedBody"><h4>Маршрут игрока</h4><select class="routeSelect" onchange="selectRouteToken(this.value)">${movable.map(t=>`<option value="${t[0]}" ${routeTokenId===t[0]?'selected':''}>${esc(t[1])}</option>`).join('')}</select><button class="${routeEdit?'on':''}" onclick="toggleRouteEdit()">${routeEdit?'✓ Маршрут редактируется':'✦ Редактировать маршрут'}</button><button onclick="clearRoute()">Очистить маршрут</button><h4>Карта арены</h4><label class="mapControl">Масштаб <b>${Math.round(sc.map?.zoom||100)}%</b><input type="range" min="100" max="180" step="1" value="${sc.map?.zoom||100}" oninput="setMapSetting('zoom',this.value)"></label><label class="mapControl">Сдвиг X <b>${Math.round(sc.map?.x||0)}</b><input type="range" min="-30" max="30" step="1" value="${sc.map?.x||0}" oninput="setMapSetting('x',this.value)"></label><label class="mapControl">Сдвиг Y <b>${Math.round(sc.map?.y||0)}</b><input type="range" min="-30" max="30" step="1" value="${sc.map?.y||0}" oninput="setMapSetting('y',this.value)"></label><label class="mapControl">Затемнение <b>${Math.round(sc.map?.dark||0)}%</b><input type="range" min="0" max="65" step="1" value="${sc.map?.dark||0}" oninput="setMapSetting('dark',this.value)"></label><button onclick="resetMapSettings()">↻ Сбросить карту</button><h4>Подписи механик</h4><div class="labelTools"><button onclick="autoArrangeEffectLabels()">✥ Развести подписи</button><button onclick="resetSceneEffectLabels()">↻ Сбросить подписи</button></div><p><b>Подпись механики можно перетаскивать отдельно от объекта.</b> Shift при перетаскивании фиксирует одну ось; двойной клик или ПКМ по подписи возвращает авто-позицию. Объекты: перетаскивание — перемещение, двойной клик — изменить текст, ПКМ — удалить. Для эффекта колесо меняет размер, Shift+колесо — поворот.</p></div></details></div></div></section>`}
function classSelectHtml(member,i){
  return `<select class="classSelect" onchange="setRosterClass(${i},this.value)"><option value="">— класс —</option>${wowClassDefs.map(c=>`<option value="${c.key}" ${member.classKey===c.key?'selected':''}>${c.name}</option>`).join('')}</select>`;
}
function rosterView(){const roster=rosterState();return `<section class="page rosterPage"><div class="rosterGrid"><div class="card"><h3>Быстрый импорт состава</h3><p>Можно указывать класс и роль: <code>Вульпяша - Priest - хил</code>, <code>HunterOne - Hunter - дд</code>. Для гибридных классов ближний/дальний бой затем можно поправить вручную.</p><textarea id="rosterInput" placeholder="TankOne - Paladin - танк\nPriestka - Priest - хил\nHunterOne - Hunter - дд"></textarea><div class="rowButtons"><button onclick="parseRoster()">Разобрать список</button><button onclick="addRosterBlank()">＋ Игрок вручную</button><button onclick="clearRoster()">Очистить</button></div></div><div class="card"><h3>Сводка</h3><div class="roleCounts"><span>🛡 ${roster.filter(x=>x.role==='tank').length} танков</span><span>♥ ${roster.filter(x=>x.role==='healer').length} хилов</span><span>⚔ ${roster.filter(x=>x.role==='dps'&&x.range==='melee').length} мили ДД</span><span>🏹 ${roster.filter(x=>x.role==='dps'&&x.range==='ranged').length} рэнж ДД</span></div><p>Класс используется как иконка игрока. Роль и дистанция используются для автоматической расстановки в шаблонах боя.</p></div></div><div class="rosterList classRoster">${roster.length?roster.map((x,i)=>{const c=wowClass(x.classKey);return `<div><span class="rosterClassIcon">${c?`<img src="${c.icon}" alt="${esc(c.name)}">`:'?'}</span><input class="rosterNameInput" value="${esc(x.name)}" onchange="setRosterName(${i},this.value)">${classSelectHtml(x,i)}<select onchange="setRosterRole(${i},this.value)"><option value="tank" ${x.role==='tank'?'selected':''}>Танк</option><option value="healer" ${x.role==='healer'?'selected':''}>Хил</option><option value="dps" ${x.role==='dps'?'selected':''}>ДД</option></select><select onchange="setRosterRange(${i},this.value)" ${x.role==='tank'?'disabled':''}><option value="melee" ${x.range==='melee'?'selected':''}>Ближний бой</option><option value="ranged" ${x.range==='ranged'?'selected':''}>Дальний бой</option></select><button class="arenaAddBtn" onclick="addRosterMemberToScene('${x.id}')" title="Добавить в текущую сцену">◎</button><button onclick="removeRoster(${i})">×</button></div>`}).join(''):'<div class="empty">Состав пока пуст.</div>'}</div>${roster.length?`<div class="rosterActions"><button onclick="placeRosterCurrentScene();setView('planner')">Расставить в текущей сцене</button><button class="primary" onclick="placeRosterAllScenes();setView('planner')">Расставить во всех сценах босса</button></div>`:''}</section>`}
function parseRoster(){
  const txt=el('#rosterInput')?.value||'';
  const lines=txt.split(/\n+/).map(x=>x.trim()).filter(Boolean);
  state.roster=lines.map((line,i)=>{
    const low=line.toLowerCase();
    const role=low.includes('танк')||/\btank\b/.test(low)?'tank':low.includes('хил')||/\bheal(?:er)?\b/.test(low)?'healer':'dps';
    const classKey=detectClassKey(line);
    const parts=line.split(/\s*[-–—|,:]\s*/).map(x=>x.trim()).filter(Boolean);
    let name=parts[0]||line;
    if(parts.length===1){
      name=line
        .replace(/\b(death\s*knight|demon\s*hunter|druid|evoker|hunter|mage|monk|paladin|priest|rogue|shaman|warlock|warrior|tank|healer|heal|dps)\b/ig,'')
        .replace(/\b(дк|дх|друид|эвокер|пробудитель|хант|охотник|маг|монк|монах|паладин|пал|прист|жрец|рога|разбойник|шаман|шам|лок|чернокнижник|вар|воин|танк|хил(?:ер)?|дд)\b/ig,'')
        .replace(/\s{2,}/g,' ').trim()||line;
    }
    return normalizeRosterMember({id:uid(),name,role,classKey,range:defaultRangeForClass(classKey,role)},i);
  });
  save();toast(`Состав: ${state.roster.length} игроков`);render();
}
function addRosterBlank(){rosterState().push(normalizeRosterMember({id:uid(),name:`Игрок ${rosterState().length+1}`,role:'dps',classKey:'',range:'ranged'},rosterState().length));save();render()}
function clearRoster(){state.roster=[];save();render()}
function setRosterName(i,v){const m=rosterState()[i];if(m){m.name=String(v||'Игрок').slice(0,30);save()}}
function setRosterClass(i,key){const m=rosterState()[i];if(!m)return;m.classKey=wowClass(key)?.key||'';m.range=defaultRangeForClass(m.classKey,m.role);save();render()}
function setRosterRole(i,r){const m=rosterState()[i];if(!m)return;m.role=r;m.range=defaultRangeForClass(m.classKey,r);save();render()}
function setRosterRange(i,r){const m=rosterState()[i];if(!m)return;m.range=r==='melee'?'melee':'ranged';save();render()}
function removeRoster(i){rosterState().splice(i,1);save();render()}
function rosterNote(){const r=rosterState();if(!r.length)return '';const f=x=>r.filter(a=>a.role===x).map(a=>`${a.name}${wowClass(a.classKey)?' ['+wowClass(a.classKey).short+']':''}`).join(', ');return `\nСостав:\nТанки: ${f('tank')||'—'}\nХилы: ${f('healer')||'—'}\nДД: ${f('dps')||'—'}`}
function timeline(b,bs){return `<section class="page timelineEditor">${rolebar()}<div class="timelineActions"><button onclick="addTimelineEvent()">＋ Событие</button><button onclick="resetTimeline()">↻ Из шаблона</button><button onclick="setView('player')">▶ Проигрыватель</button><span>Время вводится в секундах или формате м:с. Полный шаблон уже привязан к ключевым кадрам, но его можно править вручную.</span></div><div class="timeline">${bs.timelineV3.map((e,i)=>`<article class="event editEvent ${e.type}"><input value="${fmtTime(e.time)}" onchange="editTimeline(${i},'time',this.value)" aria-label="Время"><input value="${esc(e.label)}" onchange="editTimeline(${i},'label',this.value)" aria-label="Событие"><select onchange="editTimeline(${i},'type',this.value)">${Object.keys(eventTypes).map(t=>`<option value="${t}" ${e.type===t?'selected':''}>${eventTypes[t]}</option>`).join('')}</select><select onchange="editTimeline(${i},'scene',this.value)">${bs.scenes.map((s,j)=>`<option value="${j}" ${e.scene===j?'selected':''}>${j+1}. ${esc(s.name)}</option>`).join('')}</select><button onclick="moveTimeline(${i},-1)">↑</button><button onclick="moveTimeline(${i},1)">↓</button><button class="red" onclick="removeTimeline(${i})">×</button></article>`).join('')}</div></section>`}
function notes(b,bs){const ns=`[RaidRU] ${b.name}\n${b.rl}\n${priestMode?'Холи-прист: '+b.heal+'\n':''}BL: ${b.bl}${rosterNote()}\n\nТаймлайн:\n${bs.timelineV3.map(e=>`${fmtTime(e.time)} ${e.label}`).join('\n')}`;return `<section class="page notes"><div class="card wide"><h3>Личная / гильдейская заметка</h3><textarea id="customNote" oninput="saveNote(this.value)" placeholder="Назначения, хил-КД, метки…">${esc(bs.note)}</textarea></div><div class="card wide"><h3>Готовая заметка для NSRT / чата</h3><pre>${esc(ns)}</pre><button onclick="copyText(${JSON.stringify(ns)})">Копировать</button></div><div class="card checklist"><h3>Чеклист перед пулом</h3>${['Метки расставлены','Танки знают позиции','Хил-КД распределены','Soak/мини-группы назначены','Героизм согласован','Дебаффы видны на фреймах'].map(x=>`<label><input type="checkbox"> ${x}</label>`).join('')}</div></section>`}
function glossary(b){const arr=[...b.spells,...priest];return `<section class="page"><div class="table"><div class="thead"><b>Русский клиент</b><b>Английское название</b><b>Источник</b></div>${arr.map((x,i)=>`<div><b>${x[0]}</b><code>${x[1]}</code><span>${i<b.spells.length?'Босс':'Холи-прист'}</span></div>`).join('')}</div></section>`}
function chooseBoss(id){stopPlayback();stopReplay();current=id;sceneIndex=0;playerSceneIndex=0;render()} function setView(v){stopPlayback();stopReplay();view=v;render()} function setRole(v){role=v;render()} function setDiff(v){diff=v;render()} function togglePriest(){priestMode=!priestMode;render()} function fav(){const bs=bossState(current);bs.favorite=!bs.favorite;render()} function setProgress(v){bossState(current).progress=+v;save();render()} function saveNote(v){bossState(current).note=v;save()} function copyText(t){navigator.clipboard?.writeText(t);toast('Скопировано')}
function filterBoss(q){document.querySelectorAll('.bosses button').forEach(x=>x.style.display=x.dataset.name.includes(q.toLowerCase())?'grid':'none')}
function exportPlan(){const blob=new Blob([JSON.stringify({version:'0.8.3',boss:current,diff,role,data:bossState(current)},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`raidru-${current}-v083.json`;a.click();URL.revokeObjectURL(a.href);toast('Стратегия экспортирована')}
function importPlanFile(file){if(!file)return;const r=new FileReader();r.onload=()=>{try{const p=JSON.parse(r.result);if(!p.boss||!p.data)throw new Error();state[p.boss]=p.data;current=p.boss;diff=p.diff||diff;role=p.role||role;bossState(current);save();toast('Стратегия импортирована');render()}catch(e){toast('Не удалось импортировать JSON')}};r.readAsText(file)}
function sharePlan(){const u=buildShareUrl();navigator.clipboard?.writeText(u);history.replaceState(null,'',u);toast('Ссылка на стратегию скопирована')}
function backupAll(){const blob=new Blob([JSON.stringify({version:'0.8.3',savedAt:new Date().toISOString(),state},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='raidru-backup-v083.json';a.click();URL.revokeObjectURL(a.href);toast('Резервная копия скачана')}
function resetAllConfirm(){if(!confirm('Удалить локальные прогресс, планы, заметки и состав?'))return;localStorage.removeItem('raidru-standalone');location.hash='';location.reload()}
function prevScene(){sceneIndex=Math.max(0,sceneIndex-1);render()} function nextScene(){sceneIndex=Math.min(bossState(current).scenes.length-1,sceneIndex+1);render()} function goScene(i){sceneIndex=i;render()}
function loadBossPreset(){if(!confirm('Заменить текущие сцены и таймлайн готовым шаблоном босса?'))return;const bs=bossState(current);bs.scenes=bossPresetScenes(current).map((s,i)=>normalizeScene(s,current,i));bs.timelineV3=defaultTimeline(current);sceneIndex=0;save();toast('Шаблон босса и таймлайн загружены');render()}
function addScene(){const bs=bossState(current),src=bs.scenes[sceneIndex];bs.scenes.push(normalizeScene(deep({...src,name:`Сцена ${bs.scenes.length+1}`}),current,bs.scenes.length));sceneIndex=bs.scenes.length-1;save();render()}
function delScene(){const bs=bossState(current);if(bs.scenes.length<2)return;if(!confirm('Удалить сцену?'))return;bs.scenes.splice(sceneIndex,1);bs.timelineV3.forEach(e=>e.scene=Math.min(e.scene,bs.scenes.length-1));sceneIndex=Math.max(0,sceneIndex-1);save();render()}
function resetScene(){bossState(current).scenes[sceneIndex]=defaultScene();save();render()}
function setPlannerPaletteTab(tab){plannerPaletteTab=tab==='roster'?'roster':'main';save();render()}
function setPlannerIconTab(tab){plannerIconTab=tab==='search'?'search':'encounter';save();render()}
function setPlannerIconQuery(v){plannerIconQuery=String(v||'').toLowerCase();const g=el('#iconSearchGrid');if(g)g.innerHTML=searchIconGridHtml(plannerIconQuery)}
function setPlannerSpawnMode(mode){plannerSpawnMode=mode==='click'?'click':'drag';save();render()}
function plannerDragStart(e,kind,value){
  if(!e?.dataTransfer)return;
  e.dataTransfer.setData('application/x-raidru',JSON.stringify({kind,value}));
  e.dataTransfer.effectAllowed='copy';
}
function paletteClick(kind,value){
  if(plannerSpawnMode==='drag'){toast('Перетащи иконку на арену или переключи Click to Spawn');return}
  spawnPlannerItem(kind,value,50,50);
}
function addClassToken(classKey,x=50,y=50){
  const c=wowClass(classKey); if(!c)return;
  const sc=bossState(current).scenes[sceneIndex],range=defaultRangeForClass(classKey,'dps');
  sc.tokens.push([uid(),c.short,range,x,y,{kind:'class',classKey:c.key,role:'dps',range}]);save();render();
}
function addTokenAt(type,x=50,y=50){
  const sc=bossState(current).scenes[sceneIndex],labels={tank:'T',healer:'H',melee:'M',ranged:'R',boss:'БОСС'};
  sc.tokens.push([uid(),labels[type]||type,type,x,y]);save();render();
}
function addEffectAt(type,x=50,y=50){
  const sc=bossState(current).scenes[sceneIndex];sc.effects.push({id:uid(),type,x,y,w:type==='line'||type==='arrow'?40:24,h:type==='line'||type==='arrow'?6:24,rot:0,label:effectLabels[type]});save();render();
}
function addRaidMarkerAt(key,x=50,y=50){
  const sc=bossState(current).scenes[sceneIndex],m=raidMarkerDefs.find(v=>v.key===key)||raidMarkerDefs[0];
  const existing=sc.tokens.find(t=>t[2]==='marker'&&raidMarkerKey(t[1])===m.key);
  if(existing){toast(`${m.name} уже есть на этой сцене`);return}
  sc.tokens.push([uid(),m.label,'marker',x,y]);save();render();
}
function addRosterMemberToSceneAt(memberId,x=50,y=50){
  const m=rosterState().find(v=>v.id===memberId);if(!m)return;
  const sc=bossState(current).scenes[sceneIndex];
  if(sc.tokens.some(t=>rosterTokenMeta(t)?.rosterId===m.id)){toast(`${m.name} уже есть на сцене`);return}
  sc.tokens.push(rosterTokenForMember(m,{x,y}));save();render();
}
function spawnPlannerItem(kind,value,x=50,y=50){
  const sc=bossState(current).scenes[sceneIndex];let margin=0;
  if(kind==='class'||kind==='roster'||kind==='role')margin=2.45;else if(kind==='marker')margin=1.8;else if(kind==='encounter')margin=2.2;
  const p=snapArenaPoint(current,x,y,sc?.name,margin);x=p.x;y=p.y;
  if(kind==='class')return addClassToken(value,x,y);
  if(kind==='role')return addTokenAt(value,x,y);
  if(kind==='marker')return addRaidMarkerAt(value,x,y);
  if(kind==='effect')return addEffectAt(value,x,y);
  if(kind==='roster')return addRosterMemberToSceneAt(value,x,y);
  if(kind==='encounter')return addEncounterToken(value,x,y);
}
function addEncounterToken(value,x=50,y=50){const item=encounterByKey(current,value)||allEncounterIcons().find(v=>`${v.boss}:${v.key}`===value)||allEncounterIcons().find(v=>v.key===value);if(!item)return;const sc=bossState(current).scenes[sceneIndex];sc.tokens.push([uid(),item.name,'encounter',x,y,{kind:'encounter',key:item.key,boss:item.boss||current,category:item.category,icon:item.icon,name:item.name}]);save();render();}
function paletteItemAttrs(kind,value){return `draggable="true" ondragstart="plannerDragStart(event,'${kind}','${value}')" onclick="paletteClick('${kind}','${value}')"`}
function encounterGridButton(item,boss=current){const value=item.boss&&item.boss!==current?`${item.boss}:${item.key}`:item.key;const shape=['boss','npc'].includes(item.category)?'round':'square';return `<button class="encounterLibItem ${shape}" ${paletteItemAttrs('encounter',value)} title="${esc(item.name)}"><img src="${item.icon}" alt=""><span>${esc(item.name)}</span></button>`}
function currentEncounterGridHtml(){
  const named=(encounterLibrary[current]||[]).map(x=>encounterGridButton(x,current)).join('');
  const raw=current==='ulatek'?`<div class="gamePackTitle">Дополнительные игровые иконки</div><div class="encounterGrid gameRawGrid">${gameEncounterPack.map(x=>encounterGridButton(x,'ulatek')).join('')}</div>`:'';
  return `<div class="encounterGrid namedEncounterGrid">${named}</div>${raw}`;
}
function searchIconGridHtml(query=''){const q=String(query||'').toLowerCase().trim();const all=allEncounterIcons();const filtered=all.filter(x=>!q||`${x.name} ${x.aliases||''} ${raid.find(b=>b.id===x.boss)?.name||''}`.toLowerCase().includes(q));return filtered.length?filtered.map(x=>encounterGridButton(x,x.boss)).join(''):`<div class="iconSearchEmpty">Ничего не найдено</div>`}
function encounterLibraryHtml(){return `<div class="paletteSection encounterLibrary"><div class="encounterTabs"><button class="${plannerIconTab==='encounter'?'on':''}" onclick="setPlannerIconTab('encounter')">БОЙ</button><button class="${plannerIconTab==='search'?'on':''}" onclick="setPlannerIconTab('search')">ПОИСК ИКОНОК</button></div><div class="encounterToolbar"><span class="encounterBossName">${esc(raid.find(x=>x.id===current)?.name||'Босс')}</span><select onchange="setDiff(this.value)"><option value="normal" ${diff==='normal'?'selected':''}>Обычный</option><option value="heroic" ${diff==='heroic'?'selected':''}>Героический</option><option value="mythic" ${diff==='mythic'?'selected':''}>Эпохальный</option></select></div>${plannerIconTab==='encounter'?`<small class="libraryHint">Босс, существа, объекты и игровые иконки механик. Для Ула’тек ниже также доступен расширенный набор игровых иконок.</small>${currentEncounterGridHtml()}`:`<div class="iconSearch"><input placeholder="Поиск: яйцо, яд, босс, способность…" oninput="setPlannerIconQuery(this.value)" value="${esc(plannerIconQuery)}"><div id="iconSearchGrid" class="encounterGrid searchEncounterGrid">${searchIconGridHtml(plannerIconQuery)}</div></div>`}</div>`}

